// Contract PDF template builders — shared between app.js (staff UI) and contract-sign.html (public signing page).
function esc(s){return String(s).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function _sigImgTag(img){return img?`<img src="${img}" style="max-height:46px;max-width:100%">`:'';}

export function _ctRenderHtmlInPane(pane,html){
  pane.innerHTML='';
  const wrap=document.createElement('div');
  wrap.style.cssText='max-width:794px;margin:0 auto;box-shadow:0 4px 24px rgba(0,0,0,.5);background:#fff;';
  const iframe=document.createElement('iframe');
  iframe.style.cssText='border:none;width:100%;height:600px;display:block;background:#fff;';
  wrap.appendChild(iframe);
  pane.appendChild(wrap);
  const idoc=iframe.contentDocument||iframe.contentWindow.document;
  idoc.open();
  idoc.write(html);
  idoc.close();
  // Apply @page margins to body so preview matches printed output
  if(idoc.body) idoc.body.style.padding='14mm 16mm';
  // Size iframe to full document height after layout
  requestAnimationFrame(()=>requestAnimationFrame(()=>{
    try{
      const h=Math.max(idoc.body.scrollHeight,idoc.documentElement.scrollHeight,400)+20;
      iframe.style.height=h+'px';
    }catch(e){}
  }));
}

export function _ctBuildHtml(type,fields){
  const logo=BAKED_CB_LOGO;
  if(type==='presenter')return ctPresenterPDF(fields,logo);
  if(type==='contractor')return ctContractorPDF(fields,logo);
  if(type==='cap_ic')return ctCapIcPDF(fields);
  return ctRatePDF(fields,logo);
}


